import itertools

def find_counterexample(m):
    from itertools import combinations_with_replacement, permutations
    for multiset in combinations_with_replacement(range(m), m):
        if sum(multiset) % m == 0:
            continue

        # To check if ANY permutation works, we can use a simpler approach.
        # For a fixed multiset, let's check all permutations.
        # But permutations(multiset) can be up to 6! = 720, 10! = 3.6 million.
        # 10! is fine for a single multiset.

        found_perm = False
        for p in permutations(multiset):
            if sum(j * k for j, k in enumerate(p, 1)) % m == 0:
                found_perm = True
                break

        if not found_perm:
            return multiset
    return None

for m in [6, 10, 14]:
    print(f"m={m}: {find_counterexample(m)}")

