def count_prime_powers(limit):
    count = 0
    primes = []
    is_prime = [True] * (limit + 1)
    for p in range(2, limit + 1):
        if is_prime[p]:
            primes.append(p)
            for i in range(p * p, limit + 1, p):
                is_prime[i] = False

    prime_powers = set()
    for p in primes:
        pp = p
        while pp <= limit:
            prime_powers.add(pp)
            pp *= p
    return len(prime_powers)

